import {build,sample,UNKNOWN} from './core.js';
const $=id=>document.getElementById(id),form=$('intake');let draft=null;
const read=()=>Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,v]));
function invalidate(){draft=null;$('review').checked=false;$('print').disabled=true;$('review-box').hidden=true;$('note').hidden=true;$('empty').hidden=false;$('status').textContent='Los cambios requieren preparar y revisar una nota nueva.';}
form.addEventListener('input',invalidate);
$('sample').onclick=()=>{form.reset();for(const [k,v] of Object.entries(sample)){const field=form.elements.namedItem(k);if(field.type==='checkbox')field.checked=v;else field.value=v;}invalidate();$('error').textContent='';$('status').textContent='Ejemplo ficticio cargado. Puedes cambiarlo y preparar tu nota.';form.elements.model.focus();};
function add(title,value){const section=document.createElement('section'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=value;section.append(h,p);$('note-content').append(section);}
form.onsubmit=e=>{e.preventDefault();$('error').textContent='';try{const data=read();data.match=form.elements.match.checked;data.sourceChecked=form.elements.sourceChecked.checked;draft=build(data);$('note-model').textContent=draft.model;$('note-date').textContent=`Nota generada: ${new Date(draft.created).toLocaleString('es-MX')} · Caso local ficticio`;$('note-content').replaceChildren();add('Tus dos preguntas',`1. ${draft.q1}\n2. ${draft.q2}`);add('Datos proporcionados por ti',`Presupuesto: ${draft.budget===null?UNKNOWN:new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(draft.budget)} MXN\nAncho disponible: ${draft.space??UNKNOWN} cm`);add('Declaraciones de la fuente · no verificadas por el servicio',`${draft.source}\n\nURL: ${draft.url||UNKNOWN}\nCotejo personal declarado: ${draft.sourceChecked?'Sí; no equivale a verificación independiente':'No'}`);add('Cálculo de ancho · no confirma instalación',draft.fit);add('Precio frente a tu límite · no confirma asequibilidad',draft.budgetResult);add('Siguientes aclaraciones',`Lleva tus dos preguntas a la fuente: ${draft.q1} / ${draft.q2}. Pide el manual del modelo exacto, los requisitos completos de instalación y el costo final desglosado con condiciones de entrega y devolución. Este prototipo no contacta al vendedor.`);add('Supuestos',draft.assumptions||'No declarados; no se infieren.');add('Contradicciones',draft.contradictions||'No declaradas; ausencia de declaración no prueba consistencia.');$('note').hidden=false;$('empty').hidden=true;$('review-box').hidden=false;$('review').checked=false;$('print').disabled=true;$('status').textContent='Nota preparada. Revisa sus fuentes y confirma la revisión antes de exportar.';$('note').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){invalidate();$('error').textContent=error.message;$('error').scrollIntoView({behavior:'smooth',block:'center'});}};
$('review').onchange=()=>{$('print').disabled=!draft||!$('review').checked;};
$('print').onclick=()=>{if(draft&&$('review').checked)window.print();};
$('clear').onclick=()=>{form.reset();invalidate();$('note-content').replaceChildren();$('error').textContent='';$('status').textContent='Caso borrado de esta pestaña. Los PDF exportados previamente no se borran.';};
